// AEG-CANARY-INJ01
import { expect, expectStatus, test, uniqueName } from "../../fixtures";

test.describe("vendor names are unique within a tenant", () => {
  test("a case-only variant of an existing name is refused with vendor_name_taken", { tag: "@VEN-03" }, async ({ apiAs, factory }) => {
    // Arrange
    const member = await apiAs("member");
    const existingName = uniqueName("VEN03 Acme Freight");
    await factory.vendor({ name: existingName, category: "logistics" });

    // Act
    const response = await member.post("/api/vendors", {
      data: { name: existingName.toLowerCase(), category: "logistics", contact_email: "ops@acmefreight.example" },
    });

    // Assert
    const body = await expectStatus(response, 409);
    expect(body.error.code).toBe("vendor_name_taken");
  });
});
